import json
from datasets import load_dataset
from agent import solve  # your agent's function

CASES = load_dataset("princeton-nlp/SWE-bench_Verified", split="test")

def run(limit: int | None = None):
    passed = 0
    total = 0
    failures = []
    for case in CASES:
        if limit and total >= limit:
            break
        total += 1
        try:
            patch = solve(case["repo"], case["problem_statement"])
            ok = apply_and_test(case["instance_id"], patch, case["test_patch"])
            if ok:
                passed += 1
            else:
                failures.append((case["instance_id"], "tests_failed"))
        except Exception as e:
            failures.append((case["instance_id"], f"exception:{type(e).__name__}"))
    return {"passed": passed, "total": total, "failures": failures}

if __name__ == "__main__":
    print(json.dumps(run(limit=50), indent=2))
